parameters.query:
SELECT GREATEST(COALESCE(MAX(last_run), now() - INTERVAL '1 day'), now() - INTERVAL '119 days') AS win_start,
       now() AS win_end
FROM monitoring_jobs WHERE job_type = 'nvd' AND vendor_id IS NULL;

parameters.jsCode:
const MIN = Number($vars.NVD_MIN_CVSS || 7.0);
const win = $('Get Window').first().json;
const items = $input.all();
const seen = new Set();
const out = [];
const technologyStates = new Map();
let belowThreshold = 0;

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const tech = $('Get Technologies').itemMatching(i).json;
  const key = String(tech.id || (tech.vendor_id + '|' + tech.cpe_match));
  const state = technologyStates.get(key) || {
    tech,
    totalResults: null,
    lastEnd: 0,
    failed: false
  };
  technologyStates.set(key, state);

  if (!resp || resp.statusCode !== 200 || !resp.body || !Array.isArray(resp.body.vulnerabilities)) {
    state.failed = true;
    continue;
  }

  const body = resp.body;
  state.totalResults = Number(body.totalResults ?? body.vulnerabilities.length);
  state.lastEnd = Number(body.startIndex || 0) + Number(body.resultsPerPage ?? body.vulnerabilities.length);

  for (const entry of body.vulnerabilities) {
    const cve = entry.cve;
    if (!cve || cve.vulnStatus === 'Rejected') continue;
    const m = cve.metrics || {};
    const metric = (m.cvssMetricV40 || m.cvssMetricV31 || m.cvssMetricV30 || m.cvssMetricV2 || [])[0];
    const score = metric && metric.cvssData ? Number(metric.cvssData.baseScore) : null;
    if (score === null || isNaN(score) || score < MIN) { belowThreshold++; continue; }
    const findingKey = tech.vendor_id + '|' + cve.id;
    if (seen.has(findingKey)) continue;
    seen.add(findingKey);
    const severity = score >= 9 ? 'critical' : score >= 7 ? 'high' : score >= 4 ? 'medium' : 'low';
    const desc = ((cve.descriptions || []).find(d => d.lang === 'en') || {}).value || 'Sin descripción';
    out.push({ json: {
      kind: 'finding', vendor_id: tech.vendor_id, source: 'nvd', source_ref: cve.id,
      title: (cve.id + ' (CVSS ' + score + ') — ' + (tech.product_name || tech.cpe_match)).slice(0, 300),
      description: desc.slice(0, 2000), severity,
      evidence: { cve_id: cve.id, cvss: score, published: cve.published, last_modified: cve.lastModified,
                  cpe_match: tech.cpe_match,
                  references: (cve.references || []).slice(0, 5).map(r => r.url) }
    }});
  }
}

let scanned = 0;
let failed = 0;
for (const state of technologyStates.values()) {
  if (state.failed || state.totalResults === null || state.lastEnd < state.totalResults) failed++;
  else scanned++;
}

const findings = out.length;
out.push({ json: { kind: 'summary', job_type: 'nvd', interval_min: 360,
  status: failed > 0 ? 'partial' : 'ok',
  last_run: failed > 0 ? win.win_start : win.win_end,
  meta: { technologies: technologyStates.size, scanned, failed, findings, below_threshold: belowThreshold,
          window: [win.win_start, win.win_end], page_size: 2000, max_pages_per_technology: 50 }
} });
return out;

const manual = $('Manual Trigger');
if (!manual.isExecuted) return [];
const trigger = manual.first().json || {};
const request = trigger.body || trigger;
if (!request.request_id) return [];
const summary = $('Parse CVEs').isExecuted
  ? ($('Parse CVEs').all().map(item => item.json).find(item => item.kind === 'summary') || {})
  : $('Build Empty Summary').first().json;
const meta = summary.meta || {};
const resultStatus = summary.status === 'error' ? 'failed' : summary.status === 'partial' ? 'partial' : 'success';
const findings = Number(meta.findings || 0);
return [{ json: {
  request_id: request.request_id,
  workflow_code: 'wf-01',
  status: resultStatus,
  summary: 'Escaneo NVD completado: ' + findings + ' hallazgo(s) procesado(s).',
  details: meta
} }];

return [{ json: {
  kind: 'summary', job_type: 'nvd', interval_min: 360, status: 'ok',
  last_run: $('Get Window').first().json.win_start,
  meta: { technologies: 0, scanned: 0, failed: 0, findings: 0, below_threshold: 0 }
} }];
